import { Box, Code, Heading, Text } from "@chakra-ui/react";
import { Children, Component, type ReactNode } from "react";
import ReactMarkdown, { type Components } from "react-markdown";
import { MemoryReferenceTag, ReferenceTag } from "./ReferenceTag";
import { tokenizeReferences, type Reference, type ReferenceIndex } from "./references";

/**
 * Replaces reference names inside string children with inline tags.
 * Non-string children (nested markdown elements) are passed through — their
 * own component mapping highlights their string children in turn.
 */
type MemoryMap = Record<string, { value: unknown }> | null | undefined;

/** Memory references render their own tag (value tooltip); the rest share one. */
function renderReference(
  reference: Reference,
  name: string,
  memory: MemoryMap,
  key?: number,
): ReactNode {
  if (reference.kind === "memory") {
    return <MemoryReferenceTag key={key} name={name} value={memory?.[reference.target]?.value} />;
  }
  return <ReferenceTag key={key} name={name} reference={reference} />;
}

function highlightChildren(
  children: ReactNode,
  references: ReferenceIndex,
  memory: MemoryMap,
): ReactNode {
  return Children.map(children, (child) => {
    if (typeof child !== "string") return child;
    return tokenizeReferences(child, references).map((token, tokenIndex) =>
      token.reference
        ? renderReference(token.reference, token.display ?? token.text, memory, tokenIndex)
        : token.text,
    );
  });
}

function buildComponents(references: ReferenceIndex, memory: MemoryMap): Components {
  return {
    p: ({ children }) => (
      <Text textStyle="sm" _notLast={{ mb: "2" }}>
        {highlightChildren(children, references, memory)}
      </Text>
    ),
    ul: ({ children }) => (
      <Box as="ul" ps="5" textStyle="sm" listStyleType="disc" _notLast={{ mb: "2" }}>
        {children}
      </Box>
    ),
    ol: ({ children }) => (
      <Box as="ol" ps="5" textStyle="sm" listStyleType="decimal" _notLast={{ mb: "2" }}>
        {children}
      </Box>
    ),
    li: ({ children }) => <Box as="li">{highlightChildren(children, references, memory)}</Box>,
    h1: ({ children }) => (
      <Heading textStyle="md" mb="2">
        {highlightChildren(children, references, memory)}
      </Heading>
    ),
    h2: ({ children }) => (
      <Heading textStyle="sm" mb="2">
        {highlightChildren(children, references, memory)}
      </Heading>
    ),
    h3: ({ children }) => (
      <Heading textStyle="sm" mb="1">
        {highlightChildren(children, references, memory)}
      </Heading>
    ),
    code: ({ children, node }) => {
      // react-markdown v10 routes inline AND fenced code through `code` (no
      // `inline` prop anymore); a fenced block's position spreads across the
      // fence lines, so a differing start/end line marks it as a block.
      const isFencedBlock =
        (node?.position && node.position.start.line !== node.position.end.line) ||
        (typeof children === "string" && children.includes("\n"));
      if (isFencedBlock) {
        return <Code textStyle="xs">{children}</Code>;
      }
      // An inline code span naming a known reference renders as its reference tag.
      const text = Children.toArray(children)
        .filter((child): child is string => typeof child === "string")
        .join("");
      const reference = references.get(text);
      if (reference) {
        const display = text.startsWith("@") ? text.split(".").slice(1).join(".") : text;
        return renderReference(reference, display, memory);
      }
      return <Code textStyle="xs">{children}</Code>;
    },
  };
}

interface SkillMarkdownProps {
  readonly text: string;
  readonly references: ReferenceIndex;
  readonly memory?: Record<string, { value: unknown }> | null;
}

interface BoundaryProps {
  readonly text: string;
  readonly children: ReactNode;
}

/**
 * Never let a markdown parse/render error crash the pane — fall back to the
 * raw prose as pre-wrapped text.
 */
class MarkdownErrorBoundary extends Component<BoundaryProps, { hasError: boolean }> {
  constructor(props: BoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  render() {
    if (this.state.hasError) {
      return (
        <Text textStyle="sm" whiteSpace="pre-wrap">
          {this.props.text}
        </Text>
      );
    }
    return this.props.children;
  }
}

/** Renders one prose segment's markdown with reference highlighting. */
export function SkillMarkdown({ text, references, memory }: SkillMarkdownProps) {
  return (
    <MarkdownErrorBoundary text={text}>
      <ReactMarkdown components={buildComponents(references, memory)}>{text}</ReactMarkdown>
    </MarkdownErrorBoundary>
  );
}
